/** Contrato de S500L010CTRL: cada entry point recibe un formato IN y devuelve uno OUT. */
public interface ControlCaptacion {

    ResultadoL010<InicioOut> inicio(InicioIn in);                  // S500L010INICIO
    ResultadoL010<SolCtoOut> solicitaContrato(SolCtoIn in);        // S500L010SOLCTO
    ResultadoL010<Void>      liberaContrato(PasoCopia in);         // S500L010LIBERACTO
    // ... los demás entry points siguen el mismo patrón

    /** WS-FTO-IN-INICIO: paso del batch y número de mix (proceso) que llama. */
    record InicioIn(int paso, int mix) {}

    /** WS-FTO-OUT-INICIO: copia asignada y banderas de arranque. */
    record InicioOut(int copia, int proceso, boolean recuperacion, boolean tieneTipoCambio,
                     boolean bd03, boolean baja) {}

    /** WS-FTO-IN-SOLCTO: pide el bloqueo lógico de un contrato para una copia. */
    record SolCtoIn(int paso, int copia,
                    String contrato,            // 9(12): String para conservar ceros
                    boolean liberaAlTerminar,   // WS-I-SCTO-LIB
                    int mix) {}

    record SolCtoOut(boolean aplicaSaldoPendiente, int numeroProceso,
                     BigDecimal tipoCambio,     // 9(04)V9(04) -> escala 4
                     boolean aplicaPagoTotal, int indicadorPagoGbnp) {}
}

/** WS-FTO-IN-GRABALOG: el registro de log que la librería persiste por cada movimiento. */
public record RegistroLogIn(int funcion, int copia, long autLog, BaseLog base, int numCopia,
                            int statusReg, int folio24h,
                            LocalDate fechaMaquina, LocalTime hora,     // 9(06) COMP: AAMMDD y HHMMSS
                            Resultado resultado,                         // devolución, rechazo o normal
                            long llaveDialogo, String contrato, int claveTrans,
                            DatoClave datoClave,                         // nómina o tipo de cambio
                            long autoriza, long lineaServicioAut, BigDecimal lineaServicioPorc,
                            int tipoRespuestaS054,
                            DatoTarjeta datoTarjeta,                     // tarjeta o importe de evolución
                            String mensaje) {                            // X(861)

    public enum BaseLog { ORIGINAL, AUXILIAR }                           // IDENTBASE 1 / 2

    /** WS-I-GL-DEVOL: 1 devolución con DIF-VS-SDO, 99 rechazo con ERROR-RECHAZO en la misma memoria. */
    public sealed interface Resultado {
        record Normal() implements Resultado {}
        record Devolucion(int causa, String subcausa, BigDecimal difVsSaldo) implements Resultado {}  // 9(10)V99
        record Rechazo(int codigoError) implements Resultado {}                                      // 9(06)
    }
    /** NUM-NOMINA 9(08) o TCAMBIO 9(04)V9(04) según la clave de transacción. */
    public sealed interface DatoClave {
        record Nomina(long numero) implements DatoClave {}
        record TipoCambio(BigDecimal valor) implements DatoClave {}
    }
    /** TARJ-CRCHQRA 9(16) o AUTO-EVOL 9(14)V99 (clave 1153). La tarjeta viaja tokenizada. */
    public sealed interface DatoTarjeta {
        record Tarjeta(String token) implements DatoTarjeta {}
        record AutPendienteEvolucion(BigDecimal importe) implements DatoTarjeta {}
    }
}

/** Resultado común de todos los entry points (GIVING WS-L010-RESULT). */
public record ResultadoL010<T>(int codigo, T salida) {

    public static final int OK = 0;
    public static final int CONTRATO_OCUPADO = 8;          // dispara 00000000-TIEMPOS-CTOOCUP

    public boolean ok()              { return codigo == OK; }
    public boolean contratoOcupado() { return codigo == CONTRATO_OCUPADO; }

    /** WS-L010-RESULT es PIC 9(02): el adaptador valida el rango en lugar de truncar. */
    static int deLibreria(long valorNativo) {
        if (valorNativo < 0 || valorNativo > 99) {
            throw new ResultadoFueraDeRangoException(valorNativo);
        }
        return (int) valorNativo;
    }
}

/** WS-FTO-OUT-LEELOG: siguiente registro del log en recuperación. */
public record LeeLogOut(FinRecuperacion fin,               // 1 parcial, 2 total, otro = hay registro
                        boolean contratoBloqueado,         // SOLCTOLIB
                        boolean aplicaSaldoPendiente,
                        long registroLog,                  // 9(08)
                        RegistroLogIn.BaseLog base, int numCopia, int statusReg,
                        RegistroLogIn registro) {
    public enum FinRecuperacion { NINGUNO, PARCIAL, TOTAL }
}

@Service
@RequiredArgsConstructor
public class ControlCaptacionService implements ControlCaptacion {

    private final S500L010Gateway gateway;     // la librería nativa, un servicio remoto o su reimplementación
    private final ObservationRegistry observaciones;

    /** 0000-CALL-S500L010SOLCTO. La medición MAPLI (actividad 13) y la de L030 son un aspecto. */
    @Override
    @Observed(name = "s500.l010", contextualName = "L010SOLCTO",
              lowCardinalityKeyValues = {"actividad", "13", "proceso", "13"})
    public ResultadoL010<SolCtoOut> solicitaContrato(SolCtoIn in) {
        var r = gateway.solCto(in);
        if (r.contratoOcupado()) {
            // 00000000-TIEMPOS-CTOOCUP: proceso 32 y actividad 23 "CONTRATO OCUPADO"
            observaciones.getCurrentObservation().event(Observation.Event.of("contrato.ocupado"));
        }
        return r;
    }
}

/** Equivale a las banderas W77-ID-ENACT-MAPLI y WS-88-SI-LLAMA-S500L030PROC del programa anfitrión. */
@Configuration
@ConditionalOnProperty(prefix = "s500.instrumentacion", name = "habilitada", havingValue = "true")
class InstrumentacionConfig {
    @Bean ObservedAspect observedAspect(ObservationRegistry r) { return new ObservedAspect(r); }
}

/** Valores de WS-I-CHI-FUNC que usan los envoltorios del copybook. */
public enum FuncionConfirmHi {
    BATCH(1), FIN_BATCH(5), RESTAURA_BD03(6);
    // PRELINEA, FIN_PRELINEA y AVISO_RECUPERACION usan otros códigos en 0000-CALL-CONFIRMHI-*.
    final int codigo;
    FuncionConfirmHi(int c) { codigo = c; }
}

@Override
public ResultadoL010<Void> confirmaHi(FuncionConfirmHi funcion, ContextoPaso ctx) {
    return gateway.confirmHi(new ConfirmHiIn(ctx.paso(), ctx.copia(), funcion.codigo, ctx.mix()));
}

